package com.offlinecrop.assistant.engine

import com.google.gson.Gson
import org.junit.Assert.*
import org.junit.Test
import java.io.File

/**
 * Task 0.4: Contract check parsing mock files generated by Track A and Track B.
 * Ensures Kotlin data classes perfectly parse Contract 1 and Contract 3 JSON payloads.
 */
class MockRoundTripTest {

    private val gson = Gson()

    @Test
    fun testParseMockVisionFiles() {
        val mocksDir = File("../../mocks").let { if (it.exists()) it else File("mocks") }
        if (!mocksDir.exists()) return

        for (i in 1..5) {
            val file = File(mocksDir, "vision_$i.json")
            if (!file.exists()) continue
            val jsonStr = file.readText()
            val visionResult = gson.fromJson(jsonStr, VisionResult::class.java)

            assertNotNull("VisionResult should not be null for $file", visionResult)
            assertEquals("1.0", visionResult.schemaVersion)
            assertNotNull(visionResult.imageId)
            assertNotNull(visionResult.quality)
            if (!visionResult.unknown) {
                assertTrue(visionResult.predictions.isNotEmpty())
            }
        }
    }

    @Test
    fun testParseMockAdvisoryFiles() {
        val mocksDir = File("../../mocks").let { if (it.exists()) it else File("mocks") }
        if (!mocksDir.exists()) return

        for (i in 1..5) {
            val file = File(mocksDir, "advisory_$i.json")
            if (!file.exists()) continue
            val jsonStr = file.readText()
            val advisoryResponse = gson.fromJson(jsonStr, AdvisoryResponse::class.java)

            assertNotNull("AdvisoryResponse should not be null for $file", advisoryResponse)
            assertEquals("1.0", advisoryResponse.schemaVersion)
            assertNotNull(advisoryResponse.status)
            assertNotNull(advisoryResponse.diagnosis)
            assertNotNull(advisoryResponse.actionsNow)
        }
    }
}
